export const getReportClientErrorUrl = () => {




  return `/api/client-errors`
}

/**
 * Можно без входа (ошибка до входа тоже важна). Размер тела и частота ограничены на сервере.
 * @summary Ошибка на клиенте — в таблицу client_errors
 */
export const reportClientError = async (clientError: ClientError, options?: Parameters<typeof http>[1]): Promise<void> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return http<void>(getReportClientErrorUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(clientError)
  }
);}





export const getReportClientErrorMutationKey = () => ['reportClientError'] as const;

export const getReportClientErrorMutationOptions = <TError = ErrorType<Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reportClientError>>, TError,ReportClientErrorMutationVariables, TContext>, request?: SecondParameter<typeof http>}
): UseMutationOptions<Awaited<ReturnType<typeof reportClientError>>, TError,ReportClientErrorMutationVariables, TContext> => {

const mutationKey = getReportClientErrorMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof reportClientError>>, ReportClientErrorMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  reportClientError(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ReportClientErrorMutationResult = NonNullable<Awaited<ReturnType<typeof reportClientError>>>
    export type ReportClientErrorMutationBody = ClientError
    export type ReportClientErrorMutationError = ErrorType<Error>
    export type ReportClientErrorMutationVariables = {data: ClientError}

    /**
 * @summary Ошибка на клиенте — в таблицу client_errors
 */
export const useReportClientError = <TError = ErrorType<Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reportClientError>>, TError,ReportClientErrorMutationVariables, TContext>, request?: SecondParameter<typeof http>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof reportClientError>>,
        TError,
        ReportClientErrorMutationVariables,
        TContext
      > => {
      return useMutation(getReportClientErrorMutationOptions(options), queryClient);
    }

